// parity.mjs — the site's playground (docs/assets/js/ops-check.js) must agree with the ROM
// OPS_TABLE + OPS_RULES (via docs/_data/ops.json, generated by scripts/site-data.py), and every
// rule it can name must exist in refusal.c (docs/_data/rules.json). Run by `make site-check`.
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const require = createRequire(import.meta.url);
const Ops = require(path.join(root, "docs/assets/js/ops-check.js"));
const rows = JSON.parse(readFileSync(path.join(root, "docs/_data/ops.json"), "utf8"));
const rules = new Set(JSON.parse(readFileSync(path.join(root, "docs/_data/rules.json"), "utf8")).map((r) => r.id));

let bad = 0;
for (const r of rows) {
  const got = Ops.line(r.line);
  const want = r.expect === "ok" ? "ok" : r.rule;
  const have = got.kind === "ok" || got.kind === "blank" ? "ok" : got.rule;
  if (have !== want) { bad++; console.error(`MISMATCH ${JSON.stringify(r.line)}: rom=${want} site=${have} (${got.msg || ""})`); }
  if (got.rule && !rules.has(got.rule)) { bad++; console.error(`UNKNOWN RULE ${got.rule} for ${r.line}`); }
}
// whole-script behavior bench guarantees: a parse fault stops everything before any frame.
const s = Ops.script("WRITE fs hold/a ok\nWRITE fs main/x hi\n");
if (s.parseFault?.rule !== "write-ring" || s.frames !== 0 || s.exit !== 1) { bad++; console.error("script: parse fault must stop before any frame"); }
const t = Ops.script("WAIT 1\nREAD fb main/x\nWAIT 1\n");
if (t.stop?.rule !== "slot-pulled" || t.frames !== 2) { bad++; console.error("script: run-time deny must stop at its frame"); }

// every rule id the verb explorer links must exist in refusal.c
const verbsYml = readFileSync(path.join(root, "docs/_data/verbs.yml"), "utf8");
for (const m of verbsYml.matchAll(/^\s*rules: \[([^\]]*)\]/gm))
  for (const id of m[1].split(",").map((x) => x.trim()).filter(Boolean))
    if (!rules.has(id)) { bad++; console.error(`verbs.yml names unknown rule ${id}`); }

if (bad) { console.error(`parity: ${bad} disagreement(s)`); process.exit(1); }
console.log(`parity: site checker agrees with the ROM ops table (${rows.length} rows, ${rules.size} rules)`);
